Both triangles are right-angled. Which test proves that $\Delta ABC \sim \Delta PQR$?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.5]
\usetikzlibrary{calc}
\coordinate (C) at (0,0);
\coordinate (B) at (6,0);
\coordinate (A) at (0,4.5);
\draw (C) -- (B) node[midway,below,font=\small] {$12$};
\draw (A) -- (B) node[midway,above right,font=\small] {$15$};
\draw (C) -- (A);
\coordinate (c1) at ($(C)!0.6cm!(B)$);
\coordinate (c2) at ($(C)!0.6cm!(A)$);
\draw (c1) -- ($(c1)+(c2)-(C)$) -- (c2);
\node[below left] at (C) {$C$};
\node[below right] at (B) {$B$};
\node[above left] at (A) {$A$};
\coordinate (R) at (8.5,0);
\coordinate (Q) at (12.5,0);
\coordinate (P) at (8.5,3);
\draw (R) -- (Q) node[midway,below,font=\small] {$8$};
\draw (P) -- (Q) node[midway,above right,font=\small] {$10$};
\draw (R) -- (P);
\coordinate (r1) at ($(R)!0.6cm!(Q)$);
\coordinate (r2) at ($(R)!0.6cm!(P)$);
\draw (r1) -- ($(r1)+(r2)-(R)$) -- (r2);
\node[below left] at (R) {$R$};
\node[below right] at (Q) {$Q$};
\node[above left] at (P) {$P$};
\end{tikzpicture}
[/tikz]

