\draw (A) -- (C);
\draw (B) -- (C) node[midway,below,font=\small] {$x$};
\draw (D) -- (E) node[midway,above,font=\small] {$4$};
\node[left,font=\small] at ($(A)!0.5!(D)$) {$3$};
\node[left,font=\small] at ($(D)!0.5!(B)$) {$6$};
\draw[->] ($(D)!0.4!(E)$) -- ($(D)!0.55!(E)$);
