A $1.6$ m tall student casts a $2$ m shadow. At the same moment a nearby tree casts a $15$ m shadow. The sun's rays make equal angles, so the two right-angled triangles are similar. How tall is the tree?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=1.0]
\usetikzlibrary{calc}
\coordinate (G) at (7,0);
\coordinate (S) at (6.3,0);
\coordinate (T) at (0.4,0);
\coordinate (Sp) at (6.3,0.56);
\coordinate (Tp) at (0.4,4.2);
\draw (T) -- (G);
\draw (S) -- (Sp);
\draw (T) -- (Tp);
\draw (G) -- (Tp);
\coordinate (s1) at ($(S)!0.2cm!(G)$);
\coordinate (s2) at ($(S)!0.2cm!(Sp)$);
\draw (s1) -- ($(s1)+(s2)-(S)$) -- (s2);
\coordinate (t1) at ($(T)!0.2cm!(G)$);
\coordinate (t2) at ($(T)!0.2cm!(Tp)$);
\draw (t1) -- ($(t1)+(t2)-(T)$) -- (t2);
\node[below,font=\small] at ($(G)!0.5!(S)$) {$2$};
\node[below,font=\small] at ($(S)!0.5!(T)$) {$13$};
\node[right,font=\small] at ($(S)!0.5!(Sp)$) {$1.6$};
\node[left,font=\small] at ($(T)!0.5!(Tp)$) {$h$};
\node[below] at (G) {$G$};
\node[below] at (S) {$S$};
\node[below] at (T) {$T$};
\end{tikzpicture}
[/tikz]

